import{_ as t,o as a,c as l,aw as e}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Юнит-тесты","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/pyramid/unit-test.md","filePath":"wiki/dev-commit/testing/testing/pyramid/unit-test.md"}'),r={name:"wiki/dev-commit/testing/testing/pyramid/unit-test.md"};function n(o,i,s,c,d,m){return a(),l("div",null,[...i[0]||(i[0]=[e('<h1 id="юнит-тесты" tabindex="-1">Юнит-тесты <a class="header-anchor" href="#юнит-тесты" aria-label="Permalink to &quot;Юнит-тесты&quot;">​</a></h1><ul><li><strong>Юнит-тесты</strong> позволяет проверить на корректность отдельные модули исходного кода программы (функции, методы и классы) в изоляции от остальной программы (а всё остальное имитируется/заменяется). Они должны быть написаны на том же языке, что и тестируемый продукт и храниться в том же репозитории. Обычно пишутся разработчиками. Они часто прогоняются как часть сборки, чтобы сразу же увидеть успешно ли завершается тест или нет</li><li>Тест является спецификацией метода класса, контрактом: какие входные параметры ожидает этот метод, и что остальные компоненты системы ждут от него на выходе</li><li>Тесты белого ящика</li><li>Цель: изолировать отдельные части программы и показать, что по отдельности эти части работоспособны</li><li>Идея: писать тесты для каждой нетривиальной функции или метода. Это позволяет достаточно быстро проверить, не привело ли очередное изменение кода к регрессии, то есть к появлению ошибок в уже оттестированных местах программы, а также облегчает обнаружение и устранение таких ошибок</li></ul><h3 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h3><ol><li>Поощрение изменений. Поощряет программистов к изменениям кода, поскольку достаточно легко проверить, что код работает и после изменений</li><li>Упрощение интеграции. Может быть использовано для подхода к тестированию «снизу вверх»: сначала тестируя отдельные части программы, а затем программу в целом</li><li>Документирование кода. Можно рассматривать как «живой документ» для тестируемого класса</li><li>Отделение интерфейса от реализации. Поскольку некоторые классы могут использовать другие классы, тестирование отдельного класса часто распространяется на связанные с ним. Например, класс пользуется базой данных; в ходе написания теста программист обнаруживает, что тесту приходится взаимодействовать с базой. Это ошибка, поскольку тест не должен выходить за границу класса. В результате разработчик абстрагируется от соединения с базой данных и реализует этот интерфейс, используя свой собственный mock-объект. Это приводит к менее связанному коду, минимизируя зависимости в системе</li></ol><h3 id="когда-не-работает" tabindex="-1">Когда не работает <a class="header-anchor" href="#когда-не-работает" aria-label="Permalink to &quot;Когда не работает&quot;">​</a></h3><ol><li>Сложный код</li><li>Результат известен лишь приблизительно</li><li>Код, взаимодействующий с системой. Код, взаимодействующий с портами, таймерами и прочими «нестабильными» частями системы, крайне сложно проверить в изолированном окружении</li><li>Ошибки интеграции и производительности. При выполнении юнит-тестов происходит тестирование каждого из модулей по отдельности. Это означает, что ошибки интеграции, системного уровня, функций, исполняемых в нескольких модулях, не будут определены</li><li>При общей низкой культуре программирования. Для получения выгоды от модульного тестирования требуется строго следовать технологии тестирования на всём протяжении процесса разработки программного обеспечения. Нужно хранить не только записи обо всех проведённых тестах, но и обо всех изменениях исходного кода во всех модулях. С этой целью следует использовать систему контроля версий ПО. Таким</li><li>Проблемы с объектами-заглушками</li></ol><h3 id="библиотеки-для-javascript" tabindex="-1">Библиотеки для JavaScript <a class="header-anchor" href="#библиотеки-для-javascript" aria-label="Permalink to &quot;Библиотеки для JavaScript&quot;">​</a></h3><ul><li>Mocha (тестовый фреймворк)</li><li>Jest</li><li>Chai («assertion library», используется совместно с тестовым framework’ом)</li><li>Sinon.JS (библиотека для создания mock’ов, stub’ов, spy’ев, используется совместно с тестовым framework’ом)</li><li>Karma runner (от создателей Angular.JS, «test runner» — организует среду выполнения тестов)</li><li>QUnit (от создателей jQuery)</li><li>JsUnit (больше не поддерживается создателями)</li><li>Jasmine (рекомендован создателями jsUnit)</li><li>D.O.H</li></ul>',8)])])}const _=t(r,[["render",n]]);export{h as __pageData,_ as default};
